// Catppuccin Mocha theme for Typst
// Import with: #import "@preview/catppuccin.typ" or #import "path/to/catppuccin.typ"

// ── Palette ────────────────────────────────────────────────
#let base      = rgb("#1e1e2e")
#let mantle    = rgb("#181825")
#let crust     = rgb("#11111b")
#let surface0  = rgb("#313244")
#let surface1  = rgb("#45475a")
#let surface2  = rgb("#585b70")
#let overlay0  = rgb("#6c7086")
#let overlay1  = rgb("#7f849c")
#let overlay2  = rgb("#9399b2")
#let subtext0  = rgb("#a6adc8")
#let subtext1  = rgb("#bac2de")
#let text      = rgb("#cdd6f4")
#let rosewater = rgb("#f5e0dc")
#let flamingo  = rgb("#f2cdcd")
#let pink      = rgb("#f5c2e7")
#let mauve     = rgb("#cba6f7")
#let red       = rgb("#f38ba8")
#let maroon    = rgb("#eba0ac")
#let peach     = rgb("#fab387")
#let yellow    = rgb("#f9e2af")
#let green     = rgb("#a6e3a1")
#let teal      = rgb("#94e2d5")
#let sky       = rgb("#89dceb")
#let sapphire  = rgb("#74c7ec")
#let blue      = rgb("#89b4fa")
#let lavender  = rgb("#b4befe")

// ── Page ──────────────────────────────────────────────────
#set page(
  fill: base,
  margin: (x: 1.8em, y: 1.5em),
)

// ── Text ──────────────────────────────────────────────────
#set text(
  font: ("Libertinus Serif", "Noto Serif", "DejaVu Serif"),
  fill: text,
  size: 11pt,
  lang: "en",
)

// ── Headings ──────────────────────────────────────────────
#set heading(
  fill: lavender,
)

#show heading.where(level: 1): it => {
  v(0.4em)
  text(size: 1.6em, weight: "bold", fill: mauve, it.body)
  v(0.15em)
  line(length: 100%, stroke: (paint: surface1, thickness: 1pt))
  v(0.3em)
}

#show heading.where(level: 2): it => {
  v(0.3em)
  text(size: 1.25em, weight: "semibold", fill: blue, it.body)
  v(0.2em)
}

